def contains(a, x):
    if not a:
        return False
    mid = len(a) // 2
    if a[mid] == x:
        return True
    return contains(a[:mid], x) if x < a[mid] else contains(a[mid + 1:], x)
# looks O(log n); slices cost n/2 + n/4 + ... = O(n)

